    if n % 2 == 0:
        count = count + 1
print("Even numbers =", count)

numbers = [12, 45, 7, 30]
largest = numbers[0]
second = numbers[0]
for n in numbers:
    if n > largest:
        second = largest
        largest = n
    elif n > second and n != largest:
        second = n
print("Second largest =", second)
